package org.brightstats.stats;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
public final class SensitivityChecks {
 static int checks;static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);Files.createDirectories(out);Random rng=new Random(9921);double[][] data=new double[60][1];List<String> ids=new ArrayList<>();for(int i=0;i<60;i++){data[i][0]=.2+rng.nextGaussian();ids.add("Cluster "+i/3);}data[59][0]=7;data[5][0]=Double.NaN;var model=SimulationChecks.meanModel(.1);var options=new SemSensitivity.InfluenceOptions(SemSensitivity.Unit.CASE,List.of(),100,FimlSem.Options.defaults());var influence=SemSensitivity.influence(data,null,model,options,null);double mean=Arrays.stream(data).filter(r->Double.isFinite(r[0])).mapToDouble(r->r[0]).average().orElseThrow();for(var deletion:influence.deletions()){int row=Integer.parseInt(deletion.unit())-1;double delta=Double.isFinite(data[row][0])?(data[row][0]-mean)/58:0;require(deletion.usable()&&Math.abs(deletion.changes()[0]-delta)<1e-7,"Exact mean deletion change");require(Math.abs(deletion.generalizedCookDistance()-59*delta*delta)<1e-7,"Known-variance generalized Cook distance");require(Math.abs(deletion.likelihoodDisplacement()-59*delta*delta)<1e-7,"Full-data likelihood displacement");}require(influence.deletions().getLast().generalizedCookDistance()>influence.deletions().getFirst().generalizedCookDistance(),"Planted influential row is visible without automatic removal");var clustered=SemSensitivity.influence(data,ids,model,new SemSensitivity.InfluenceOptions(SemSensitivity.Unit.CLUSTER,List.of(),100,FimlSem.Options.defaults()),null);require(clustered.deletions().size()==20&&clustered.deletions().stream().allMatch(d->d.removedSourceRows().size()==3),"Whole-cluster influence units are preserved");
 var fixed=new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of());var variance=new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of(new SemModel.Parameter("Mean",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,0,0)),1,1,1e-7,null)));var bad=new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{-1}},new double[1],List.of());var candidates=List.of(new SemSensitivity.Candidate("Free mean",model,FimlSem.Options.defaults()),new SemSensitivity.Candidate("Fixed zero mean",fixed,FimlSem.Options.defaults()),new SemSensitivity.Candidate("Different estimand with same label",variance,FimlSem.Options.defaults()),new SemSensitivity.Candidate("Inadmissible model",bad,FimlSem.Options.defaults()));var multiverse=SemSensitivity.multiverse(data,candidates,false,null);require(multiverse.alternatives().size()==4&&multiverse.alternatives().stream().filter(SemSensitivity.Alternative::regular).count()==3,"Failed alternatives retained without replacement");require(multiverse.comparableParameterRanges().size()==2&&multiverse.comparableParameterRanges().stream().allMatch(r->r.availableRegularFits()==1),"Matching parameter labels cannot merge different estimands");var complete=SemSensitivity.multiverse(data,candidates,true,null);require(complete.commonSourceRows().size()==59&&!complete.commonSourceRows().contains(6),"Complete cases are selected once with original row identity");require(!complete.sourceDataSha256().equals(multiverse.sourceDataSha256()),"Common-sample selection changes identity");try{SemSensitivity.influence(data,null,model,new SemSensitivity.InfluenceOptions(SemSensitivity.Unit.CASE,List.of(),3,FimlSem.Options.defaults()),null);throw new AssertionError("Deletion budget silently sampled rows");}catch(IllegalArgumentException expected){checks++;}Thread.currentThread().interrupt();try{SemSensitivity.multiverse(data,candidates,false,null);throw new AssertionError("Sensitivity cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
 var gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject result=new JsonObject();result.add("data",gson.toJsonTree(data));result.add("clusterIds",gson.toJsonTree(ids));result.add("influence",gson.toJsonTree(influence));result.add("clusterInfluence",gson.toJsonTree(clustered));result.add("candidates",gson.toJsonTree(candidates));result.add("multiverse",gson.toJsonTree(multiverse));result.add("complete",gson.toJsonTree(complete));result.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),gson.toJson(result));System.out.println("Sensitivity checks: "+checks);
 }
}
